/**\n     * Import products from CSV file.\n     */\n    public function importProductsFromCsv(string $filePath): array\n    {\n        if (!File::exists($filePath)) {\n            throw new \\Exception(\"CSV file not found: {$filePath}\");\n        }\n\n        $handle = fopen($filePath, 'r');\n        $headers = fgetcsv($handle, 1000, ',');\n        $products = [];\n\n        while (($row = fgetcsv($handle, 1000, ',')) !== false) {\n            $rowData = array_combine(array_map('strtolower', $headers), $row);\n            $product = $this->syncProduct($rowData);\n            $products[] = $product;\n        }\n\n        fclose($handle);\n\n        return $products;\n    }\n\n    /**\n     * Sync an order from CSV data and create stock-take job.\n     */\n    public function syncOrder(array $orderData): \\App\\Models\\StocktakeJob\n    {\n        $normalized = $this->normalizeOrder($orderData);\n        $this->validateOrderRequirements($normalized);\n        $products = $this->syncProducts($normalized['items'] ?? []);\n\n        $job = \\App\\Models\\StocktakeJob::create([\n            'tenant_id' => $this->tenant->id,\n            'reference' => 'EXT-CSV-' . strtoupper(Str::random(8)),\n            'title' => $normalized['title'] ?? 'CSV Stock-take',\n            'status' => 'in_progress',\n            'stocktake_type' => 'external_pos',\n            'external_system' => $this->name,\n            'external_reference' => $normalized['external_reference'] ?? null,\n            'scope_config' => $normalized['scope_config'] ?? [],\n            'recurrence_config' => $normalized['recurrence_config'] ?? null,\n            'mode' => $normalized['mode'] ?? 'proposed',\n            'frequency' => $normalized['frequency'] ?? 'on_demand',\n            'minimum_team_size' => $normalized['minimum_team_size'] ?? 1,\n            'estimated_duration_hours' => $normalized['estimated_duration_hours'] ?? 4,\n        ]);\n\n        if (!empty($products)) {\n            $job->products()->syncWithoutDetaching(array_pluck($products, 'id'));\n        }\n\n        return $job;\n    }\n"    {\n        $items = [];\n        foreach ($data['rows'] ?? $data['items'] ?? [] as $row) {\n            $items[] = [\n                'product_name' => $row['product_name'] ?? $row['name'] ?? '',\n                'sku' => $row['sku'] ?? $row['product_sku'] ?? '',\n                'barcode' => $row['barcode'] ?? $row['product_barcode'] ?? '',\n                'quantity' => (int)($row['quantity'] ?? 1),\n                'unit' => $row['unit'] ?? 'piece',\n                'unit_price' => (float)($row['unit_price'] ?? $row['price'] ?? 0),\n                'line_total' => (float)($row['line_total'] ?? $row['total'] ?? 0),\n                'tax_amount' => (float)($row['tax_amount'] ?? 0),\n                'discount_amount' => (float)($row['discount_amount'] ?? 0),\n            ];\n        }\n        return [\n            'title' => $data['title'] ?? 'CSV Stock-take',\n            'external_reference' => $data['external_reference'] ?? null,\n            'scope_config' => $data['scope_config'] ?? [],\n            'recurrence_config' => $data['recurrence_config'] ?? null,\n            'mode' => $data['mode'] ?? 'proposed',\n            'frequency' => $data['frequency'] ?? 'on_demand',\n            'minimum_team_size' => (int)($data['minimum_team_size'] ?? 1),\n            'estimated_duration_hours' => (int)($data['estimated_duration_hours'] ?? 4),\n            'items' => $items,\n        ];\n    }\n"